// prompt: "pick either a circle, rectangle, or triangle and use only that geometric shape"
//

mat2 ROTM(float ang) { return mat2(cos(ang),sin(ang),-sin(ang),cos(ang)); }

#define PI2 6.2831853072

vec2 g_cs;

float linstep(float a, float b, float x) { return clamp((x-a)/(b-a),0.,1.); }

float mylength(vec2 p)
{
    float N=3.+.15*iTime*iTime;
    N=floor(N)+smoothstep(.6,1.,fract(N));
    float ang=atan(p.y,p.x); if (ang<0.) ang+=PI2;
    g_cs=cos((floor(ang/(PI2/N))+.5)*(PI2/N)-vec2(0,PI2*.25));
    return dot(p,g_cs);
}

void mainImage( out vec4 fragColor, in vec2 fragCoord )
{
    int NUM=40;
    vec3 col=vec3(0);
    for(int i=0;i<NUM;i++){
        float fi=1.-float(i)/float(NUM-1);
        float r=(fi+.07)*iResolution.x*.5;
        vec2 p=r*.7*cos(fi*1.57*4.*4.*vec2(1,.7)+iTime*3.-vec2(0,1.57))+iResolution.xy*.5;
        vec2 dp=fragCoord-p;
        mat2 rot=ROTM(r/iResolution.x*13.-iTime);
        float l=mylength(dp*rot);
        float mask=1.-linstep(0.,6.,l-r);
        float maskSm=1.-linstep(0.,10.*r/40.,l-r);
        vec3 n=normalize(vec3(1.5,rot*g_cs*sin(l*.75/mix(sqrt(r*.3),1.,sin(iTime)*.5+.5))));
        float br=1.-.7*fi;
        vec3 ci=(n*.5+.5)*br;
        vec3 dir=vec3((fragCoord-iResolution.xy*.5)/(iResolution.x*.5),-.7);
        vec3 rdir=reflect(dir,n).xyz;
        rdir.xy*=ROTM(iTime);
        ci=mix(vec3(.2,.3,.4)*.7,textureLod(iChannel0,rdir,5.5).xyz*mask,br);
        col=mix(col,ci,mask*.6+maskSm*.4);
    }
    fragColor=vec4(col,1);
}
